struct Shape {
    virtual ~Shape() {}
    virtual Shape* clone() const = 0;
};

struct Circle : Shape {
    Circle* clone() const override { return new Circle(*this); }  // covariant
};

template <class D, class B>
struct Cloneable : B {
    std::unique_ptr<B> clone() const override {
        return std::unique_ptr<B>(new D(static_cast<const D&>(*this)));
    }
};

struct Circle : Cloneable<Circle, Shape> { int radius = 0; };
